    render_bar_chart(20, 190, 600, 120);

    // Tabla de últimas órdenes
    draw_table(20, 325, 600, 140, ["FECHA", "CLIENTE", "PLAN", "MONTO", "ESTADO"], transacciones);

    FRAME;
  END
END
