        if (key(_down))  advance(-4); end;
        if (key(_left))  angle += 1000; end;
        if (key(_right)) angle -= 1000; end;

        if (key(_q))     xadvance(4, 90000);  end;
        if (key(_e))     xadvance(4, -90000); end;

        FRAME;
    END

ONEXIT
    stop_raycast();
END
